values
  ('neet-biology-principles-of-inheritance-and-variations', 'neet-biology', 'Principles of Inheritance and Variations', 'principles-of-inheritance-and-variations', 25),
  ('neet-biology-molecular-basis-of-inheritance', 'neet-biology', 'Molecular Basis of Inheritance', 'molecular-basis-of-inheritance', 26),
