insert into public.formula_cards (
  id, chapter_id, title, card_type, body, formulas, variables, conditions, table_data, diagram_data, diagram_svg, recall_data, importance, source_page, sort_order, is_active
)
values
  ('neet-biology-principles-of-inheritance-and-variations-genetics-terms', 'neet-biology-principles-of-inheritance-and-variations', 'Genetics Core Terms', 'concept', 'Genetics studies inheritance, heredity and variation of characters.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall"],"rows":[["Genetics","Study of inheritance, heredity and variation of characters; or study of genes and chromosomes"],["Inheritance","Transmission of characters from parents to progeny"],["Variation","Difference between parents and offspring"],["Character","A heritable feature, such as eye colour"],["Trait","Variant of a character, such as brown eye or blue eye"],["Allele","Alternative form of a gene, such as T and t for height"]]}'::jsonb, null, null, '{"recall_question":"What is inheritance?","reveal_answer":"Transmission of characters from parents to progeny.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 107, 1, true),
  ('neet-biology-principles-of-inheritance-and-variations-genotype-vs-phenotype', 'neet-biology-principles-of-inheritance-and-variations', 'Genotype vs Phenotype', 'comparison', 'Phenotype is visible expression; genotype is genetic constitution.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed meaning"],"rows":[["Phenotype","Physical expression of a character"],["Genotype","Genetic constitution of a character"]]}'::jsonb, null, null, '{"recall_question":"Which term means genetic constitution of a character?","reveal_answer":"Genotype.","key_points":[],"examples":[],"neet_traps":["Phenotype is physical expression."]}'::jsonb, 5, 107, 2, true),
  ('neet-biology-principles-of-inheritance-and-variations-homozygous-vs-heterozygous', 'neet-biology-principles-of-inheritance-and-variations', 'Homozygous vs Heterozygous', 'comparison', 'Allelic similarity or dissimilarity determines homozygous and heterozygous conditions.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall","Examples"],"rows":[["Homozygous","Chromosome pair carries similar alleles of a gene; pure line or true breeding","TT, tt, YY, yy"],["Heterozygous","Chromosome pair carries dissimilar alleles of a gene","Tt, Yy"]]}'::jsonb, null, null, '{"recall_question":"Which condition is also called pure line?","reveal_answer":"Homozygous.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 107, 3, true),
  ('neet-biology-principles-of-inheritance-and-variations-mendel-pea-work', 'neet-biology-principles-of-inheritance-and-variations', 'Mendel and Garden Pea', 'fact', 'Gregor Mendel conducted hybridization experiments on garden peas for seven years.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Scientist","Gregor Mendel, Father of genetics"],["Plant","Garden pea, Pisum sativum"],["Duration","7 years, 1856-1863"],["Cross steps","Select contrasting plants, emasculate female parent, pollinate, collect and germinate seeds"]]}'::jsonb, null, null, '{"recall_question":"Which plant did Mendel use for hybridization experiments?","reveal_answer":"Garden pea, Pisum sativum.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 107, 4, true),
  ('neet-biology-principles-of-inheritance-and-variations-pea-contrasting-traits', 'neet-biology-principles-of-inheritance-and-variations', 'Seven Pea Contrasting Traits', 'fact', 'Mendel selected seven pairs of true breeding pea varieties.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Character","Dominant","Recessive"],"rows":[["Stem height","Tall","Dwarf"],["Flower colour","Violet","White"],["Flower position","Axial","Terminal"],["Pod shape","Inflated","Constricted"],["Pod colour","Green","Yellow"],["Seed shape","Round","Wrinkled"],["Seed colour","Yellow","Green"]]}'::jsonb, null, null, '{"recall_question":"In pea seed colour, which trait is dominant in the source?","reveal_answer":"Yellow.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 107, 5, true),
  ('neet-biology-principles-of-inheritance-and-variations-monohybrid-cross', 'neet-biology-principles-of-inheritance-and-variations', 'Monohybrid Cross', 'diagram', 'A monohybrid cross involves two plants differing in one character pair.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage","Source-backed recall"],"rows":[["Parent cross","Tall pea plant crossed with dwarf pea plant"],["F1","Tt, tall"],["F2 phenotypic ratio","3 Tall : 1 Dwarf = 3:1"],["F2 genotypic ratio","1 Homozygous tall : 2 Heterozygous tall : 1 Homozygous dwarf = 1:2:1"]]}'::jsonb, '{"type":"bio-monohybrid-cross"}'::jsonb, null, '{"recall_question":"What is the monohybrid phenotypic ratio?","reveal_answer":"3 Tall : 1 Dwarf = 3:1.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 107, 6, true),
  ('neet-biology-principles-of-inheritance-and-variations-law-of-dominance', 'neet-biology-principles-of-inheritance-and-variations', 'Law of Dominance', 'concept', 'Mendel''s first law explains dominance in a dissimilar pair of factors.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Statement point","Source-backed wording"],"rows":[["Control","Characters are controlled by discrete units called factors"],["Pairing","Factors occur in pairs"],["Dominance","In a dissimilar pair, one member dominates the other"]]}'::jsonb, null, null, '{"recall_question":"Which Mendelian law says factors occur in pairs?","reveal_answer":"Law of dominance.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 108, 7, true),
  ('neet-biology-principles-of-inheritance-and-variations-law-of-segregation', 'neet-biology-principles-of-inheritance-and-variations', 'Law of Segregation', 'concept', 'Alleles of a character pair segregate during gamete formation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Parent condition","Gametes produced"],"rows":[["Homozygous parent","Similar gametes"],["Heterozygous parent","Two kinds of gametes"]]}'::jsonb, null, null, '{"recall_question":"Which Mendelian law explains separation of alleles during gamete formation?","reveal_answer":"Law of segregation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 108, 8, true),
  ('neet-biology-principles-of-inheritance-and-variations-backcross-testcross', 'neet-biology-principles-of-inheritance-and-variations', 'Backcross and Testcross', 'comparison', 'Testcross is used to find the unknown genotype of a character.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cross","Source-backed recall"],"rows":[["Backcross","Cross between a hybrid and any parent"],["Testcross","Crossing an organism with dominant phenotype to a recessive individual"],["Monohybrid test cross ratio","1:1"],["All violet result","Unknown flower is homozygous dominant"],["50% violet, 50% white","Unknown flower is heterozygous"]]}'::jsonb, null, null, '{"recall_question":"What is the monohybrid test cross ratio?","reveal_answer":"1:1.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 107, 9, true),
  ('neet-biology-principles-of-inheritance-and-variations-dihybrid-cross', 'neet-biology-principles-of-inheritance-and-variations', 'Dihybrid Cross', 'diagram', 'A dihybrid cross studies two pairs of contrasting characters.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Parent cross","RRYY x rryy"],["F1","RrYy, round yellow"],["Gametes","RY, Ry, rY, ry"],["F2 phenotypic ratio","9 Round yellow : 3 Round green : 3 Wrinkled yellow : 1 Wrinkled green = 9:3:3:1"],["F2 genotypic ratio","1:2:1:2:4:2:1:2:1"]]}'::jsonb, '{"type":"bio-dihybrid-ratio"}'::jsonb, null, '{"recall_question":"What is Mendel''s dihybrid phenotypic ratio?","reveal_answer":"9:3:3:1.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 108, 10, true),
  ('neet-biology-principles-of-inheritance-and-variations-law-independent-assortment', 'neet-biology-principles-of-inheritance-and-variations', 'Law of Independent Assortment', 'concept', 'Mendel''s third law is based on results of dihybrid crosses.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed statement"],"rows":[["Basis","Dihybrid crosses"],["Statement","When two pairs of traits are combined in a hybrid, segregation of one pair of characters is independent of the other pair of characters"]]}'::jsonb, null, null, '{"recall_question":"Which law is based on dihybrid crosses?","reveal_answer":"Law of independent assortment.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 108, 11, true),
  ('neet-biology-principles-of-inheritance-and-variations-dominance-concept', 'neet-biology-principles-of-inheritance-and-variations', 'Concept of Dominance', 'concept', 'Dominance depends on the functional effect of alleles in a heterozygote.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Allele/product","Source-backed outcome"],"rows":[["Unmodified allele","Generally dominant and represents original phenotype"],["Modified allele","Generally recessive"],["Normal or less efficient enzyme","May produce same phenotype as unmodified allele"],["Non-functional enzyme or no enzyme","Phenotype depends on functioning unmodified allele; modified allele becomes recessive"]]}'::jsonb, null, null, '{"recall_question":"What kind of allele is generally recessive in the dominance concept?","reveal_answer":"Modified allele.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 108, 12, true),
  ('neet-biology-principles-of-inheritance-and-variations-incomplete-dominance', 'neet-biology-principles-of-inheritance-and-variations', 'Incomplete Dominance', 'comparison', 'Incomplete dominance produces an intermediate heterozygous phenotype.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Definition","Heterozygous offspring shows intermediate character between parental characteristics"],["Examples","Snapdragon or dog flower, Antirrhinum sp.; Mirabilis jalapa or 4 O''clock plant"],["Cross result","Red x white produces pink"],["Phenotypic ratio","1 Red : 2 Pink : 1 White"],["Genotypic ratio","1 (RR) : 2 (Rr) : 1 (rr)"]]}'::jsonb, null, null, '{"recall_question":"What phenotype appears in the heterozygote in snapdragon incomplete dominance?","reveal_answer":"Pink flower.","key_points":[],"examples":[],"neet_traps":["Here phenotypic and genotypic ratios are same."]}'::jsonb, 5, 108, 13, true),
  ('neet-biology-principles-of-inheritance-and-variations-codominance-abo', 'neet-biology-principles-of-inheritance-and-variations', 'Codominance and ABO', 'comparison', 'In codominance, both alleles of a gene are expressed in a hybrid.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Example","ABO blood grouping in human"],["Gene","Gene I"],["Alleles","I^A, I^B and i"],["I^A and I^B together","Both express their own types of sugars"],["i allele","Does not produce any sugar"]]}'::jsonb, null, null, '{"recall_question":"Which ABO genotype shows codominance?","reveal_answer":"I^A I^B.","key_points":[],"examples":[],"neet_traps":["Codominance is not the same as multiple allelism."]}'::jsonb, 5, 108, 14, true),
  ('neet-biology-principles-of-inheritance-and-variations-abo-genotypes', 'neet-biology-principles-of-inheritance-and-variations', 'ABO Genotype Table', 'fact', 'The source lists genotype-to-phenotype outcomes for ABO blood groups.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Genotype","Blood type"],"rows":[["I^A I^A","A"],["I^A i","A"],["I^B I^B","B"],["I^B i","B"],["I^A I^B","AB"],["ii","O"]]}'::jsonb, null, null, '{"recall_question":"Which genotype gives blood group O?","reveal_answer":"ii.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 108, 15, true),
  ('neet-biology-principles-of-inheritance-and-variations-multiple-alleles-polygenic-pleiotropy', 'neet-biology-principles-of-inheritance-and-variations', 'Multiple Alleles, Polygenic Inheritance and Pleiotropy', 'comparison', 'These inheritance patterns extend beyond simple Mendelian dominance.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Pattern","Source-backed recall","Examples"],"rows":[["Multiple allelism","Presence of more than two alleles of a gene to govern same character; only two alleles are present in an individual","ABO blood grouping"],["Polygenic inheritance","Traits controlled by several genes; phenotype reflects additive contribution of alleles and environmental influence","Human skin colour, human height"],["Pleiotropy","A single gene exhibits multiple phenotypic expressions","Starch synthesis in pea, sickle cell anaemia, phenylketonuria"]]}'::jsonb, null, null, '{"recall_question":"Which pattern has more than two alleles in a population?","reveal_answer":"Multiple allelism.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 109, 16, true),
  ('neet-biology-principles-of-inheritance-and-variations-chromosomal-theory', 'neet-biology-principles-of-inheritance-and-variations', 'Chromosomal Theory of Inheritance', 'classification', 'Sutton and Boveri connected chromosome behaviour with Mendelian factors.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Year","1902"],["Proposed by","Walter Sutton and Theodore Boveri"],["Core idea","Pairing and separation of chromosomes lead to segregation of factors they carry"],["Statement","Chromosomes are vehicles of heredity"],["Morgan","Proved chromosomal theory using fruit flies, Drosophila melanogaster"]]}'::jsonb, '{"type":"bio-chromosomal-theory"}'::jsonb, null, '{"recall_question":"Who proposed chromosomal theory of inheritance?","reveal_answer":"Walter Sutton and Theodore Boveri.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 109, 17, true),
  ('neet-biology-principles-of-inheritance-and-variations-drosophila-genetic-study', 'neet-biology-principles-of-inheritance-and-variations', 'Drosophila as Genetic Material', 'fact', 'Morgan used fruit flies for genetic study because they are experimentally convenient.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Source reason","Detail"],"rows":[["Medium","Grow on simple synthetic medium"],["Life cycle","12-14 days"],["Breeding","Can be done throughout the year"],["Progeny","Hundreds of progenies per mating"],["Sex distinction","Male and female flies are easily distinguishable; male is smaller"],["Variation","Many hereditary variations visible with low power microscopes"]]}'::jsonb, null, null, '{"recall_question":"What is Drosophila''s life cycle duration in the source?","reveal_answer":"12-14 days.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 109, 18, true),
  ('neet-biology-principles-of-inheritance-and-variations-linkage-vs-recombination', 'neet-biology-principles-of-inheritance-and-variations', 'Linkage vs Recombination', 'comparison', 'Linked genes do not show independent assortment; recombination generates non-parental combinations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed recall"],"rows":[["Linkage","Physical association of two or more genes on a chromosome"],["Recombination","Generation of non-parental gene combinations due to independent assortment or crossing over"],["Tight linkage","Low recombination"],["Loose linkage","High recombination"]]}'::jsonb, '{"type":"bio-linkage-recombination"}'::jsonb, null, '{"recall_question":"Which linked genes show low recombination?","reveal_answer":"Tightly linked genes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 110, 19, true),
  ('neet-biology-principles-of-inheritance-and-variations-morgan-recombination-values', 'neet-biology-principles-of-inheritance-and-variations', 'Morgan Recombination Values', 'fact', 'Morgan''s Drosophila crosses showed deviation from 9:3:3:1 because of linkage.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Gene pair","Source-backed linkage/recombination"],"rows":[["White eye and yellow body","Very tightly linked; only 1.3% recombination"],["White eye and miniature wing","Loosely linked; 37.2% recombination"],["Sturtevant","Used recombination frequency to measure distance between genes and map chromosome positions"]]}'::jsonb, null, null, '{"recall_question":"Which Morgan gene pair showed 1.3% recombination?","reveal_answer":"White eye and yellow body.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 110, 20, true),
  ('neet-biology-principles-of-inheritance-and-variations-sex-determination-systems', 'neet-biology-principles-of-inheritance-and-variations', 'Sex Determination Systems', 'comparison', 'Sex chromosomes involved in sex determination are called allosomes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["System","Source-backed pattern","Examples"],"rows":[["XX-XO","Male heterogametic XO, female homogametic XX","Many insects such as grasshopper"],["XX-XY","Male heterogametic X and Y, female homogametic X only","Human and Drosophila"],["ZZ-ZW","Male homogametic ZZ, female heterogametic Z and W","Birds"],["Haplodiploid","Females diploid from fertilised eggs, males haploid from unfertilised eggs","Honeybee"]]}'::jsonb, '{"type":"bio-sex-determination"}'::jsonb, null, '{"recall_question":"Which sex-determination system shows female heterogamety?","reveal_answer":"ZZ-ZW mechanism.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 110, 21, true),
  ('neet-biology-principles-of-inheritance-and-variations-human-sex-determination', 'neet-biology-principles-of-inheritance-and-variations', 'Human Sex Determination', 'fact', 'In humans, the sperm determines whether the offspring is male or female.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed value/detail"],"rows":[["Human chromosomes","23 pairs: 22 pairs autosomes and 1 pair sex chromosomes"],["Female","XX; produces ovum with X chromosome"],["Male","XY; produces 50% sperms with X and 50% with Y"],["Probability","Equal probability of fertilisation with sperm carrying X or Y chromosome"]]}'::jsonb, null, null, '{"recall_question":"In humans, which gamete determines sex of offspring?","reveal_answer":"Sperm.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 110, 22, true),
  ('neet-biology-principles-of-inheritance-and-variations-honeybee-sex-determination', 'neet-biology-principles-of-inheritance-and-variations', 'Honeybee Haplodiploidy', 'fact', 'Honeybee sex determination depends on number of chromosome sets.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Individual","Source-backed origin/chromosomes"],"rows":[["Female queen or worker","Fertilised egg; diploid, 32 chromosomes"],["Male drone","Unfertilised egg by parthenogenesis; haploid, 16 chromosomes"],["Male sperm formation","By mitosis"],["Family relation trap","Males do not have father and cannot have sons, but have grandfather and can have grandsons"]]}'::jsonb, null, null, '{"recall_question":"How many chromosomes does a male honeybee have in the source?","reveal_answer":"16 chromosomes.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 110, 23, true),
  ('neet-biology-principles-of-inheritance-and-variations-mutation-types', 'neet-biology-principles-of-inheritance-and-variations', 'Mutation Types', 'classification', 'Mutation is a sudden heritable change in DNA sequence that changes genotype and phenotype.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type","Source-backed recall","Example/detail"],"rows":[["Point mutation","Change or substitution in a single base pair of DNA","Sickle cell anaemia"],["Frame-shift mutation","Deletion or insertion of base pairs shifts DNA sequences","Insertion/deletion"],["Chromosomal abnormality","Loss, gain or abnormal arrangement of chromosome/DNA segment","Seen in cancer cells"],["Mutagens","Agents inducing mutation","UV radiation, alpha, beta, gamma rays, X-ray, mustard gas, phenol, formalin"]]}'::jsonb, null, null, '{"recall_question":"What mutation type is caused by substitution in a single base pair?","reveal_answer":"Point mutation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 111, 24, true),
  ('neet-biology-principles-of-inheritance-and-variations-mendelian-vs-chromosomal-disorders', 'neet-biology-principles-of-inheritance-and-variations', 'Mendelian vs Chromosomal Disorders', 'comparison', 'Genetic disorders arise from changes in genes or chromosomes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disorder class","Source-backed cause","Examples"],"rows":[["Mendelian disorders","Alteration or mutation in a single gene","Haemophilia, colour blindness, sickle-cell anaemia, phenylketonuria, thalassemia, cystic fibrosis"],["Chromosomal disorders","Absence, excess or abnormal arrangement of one or more chromosomes","Down''s syndrome, Klinefelter''s syndrome, Turner''s syndrome"]]}'::jsonb, null, null, '{"recall_question":"Which disorder class is caused by mutation in a single gene?","reveal_answer":"Mendelian disorders.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 111, 25, true),
  ('neet-biology-principles-of-inheritance-and-variations-x-linked-disorders', 'neet-biology-principles-of-inheritance-and-variations', 'Haemophilia and Colour Blindness', 'comparison', 'Both source disorders are sex-linked X-linked recessive disorders.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disorder","Source-backed recall"],"rows":[["Haemophilia","Protein involved in blood clotting is affected; simple cut causes non-stop bleeding; Queen Victoria was a carrier"],["Colour blindness","Defect in red or green cone of eye; failure to discriminate red and green colour"],["Colour blindness frequency","8% of males and about 0.4% of females"],["Carrier woman son","Son of heterozygous woman has 50% chance of being colour blind"]]}'::jsonb, null, null, '{"recall_question":"Which X-linked disorder affects blood clotting?","reveal_answer":"Haemophilia.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 111, 26, true),
  ('neet-biology-principles-of-inheritance-and-variations-sickle-cell-anaemia', 'neet-biology-principles-of-inheritance-and-variations', 'Sickle-Cell Anaemia', 'neet_trap', 'Sickle-cell anaemia is an autosome linked recessive disease caused by a point mutation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Inheritance","Autosome linked recessive"],["Genotypes","HbA HbA normal; HbA HbS carrier; HbS HbS affected"],["Protein change","Glutamic acid replaced by Valine at sixth position of beta-globin chain"],["Codon change","GAG to GUG at sixth codon of beta-globin gene"],["RBC shape","Biconcave disc changes to elongated sickle-like structure under low oxygen tension"]]}'::jsonb, null, null, '{"recall_question":"Which amino acid replaces glutamic acid in sickle-cell anaemia?","reveal_answer":"Valine.","key_points":[],"examples":[],"neet_traps":["Sickle-cell anaemia is qualitative; thalassemia is quantitative in the source."]}'::jsonb, 5, 111, 27, true),
  ('neet-biology-principles-of-inheritance-and-variations-phenylketonuria', 'neet-biology-principles-of-inheritance-and-variations', 'Phenylketonuria', 'fact', 'Phenylketonuria is an autosomal recessive inborn error of metabolism.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Enzyme","Phenyl alanine hydroxylase"],["Normal conversion","Phenylalanine to tyrosine"],["Affected condition","Enzyme is lacking"],["Result","Phenylalanine accumulates and converts into phenyl pyruvic acid and derivatives"],["Effect","Accumulation in brain causing mental retardation; excretion through urine"]]}'::jsonb, null, null, '{"recall_question":"Which enzyme is deficient in phenylketonuria?","reveal_answer":"Phenyl alanine hydroxylase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 112, 28, true),
  ('neet-biology-principles-of-inheritance-and-variations-thalassemia', 'neet-biology-principles-of-inheritance-and-variations', 'Thalassemia', 'comparison', 'Thalassemia is an autosome-linked recessive blood disease due to mutation or deletion.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Type/cue","Source-backed detail"],"rows":[["Effect","Reduced synthesis of alpha or beta globin chains of haemoglobin"],["Alpha thalassemia","Production of alpha globin chain affected; controlled by HBA1 and HBA2 on chromosome 16 of each parent"],["Beta thalassemia","Production of beta globin chain affected; controlled by HBB on chromosome 11 of each parent"],["Thalassemia vs sickle-cell","Thalassemia is quantitative; sickle-cell anaemia is qualitative"]]}'::jsonb, null, null, '{"recall_question":"Which globin-chain disorder is quantitative in the source?","reveal_answer":"Thalassemia.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 112, 29, true),
  ('neet-biology-principles-of-inheritance-and-variations-chromosomal-disorders', 'neet-biology-principles-of-inheritance-and-variations', 'Chromosomal Disorders', 'comparison', 'Aneuploidy is gain or loss of chromosomes; polyploidy is increase in a whole set.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Disorder","Source-backed karyotype/cause","Key features"],"rows":[["Down''s syndrome","Additional chromosome 21; 45 A + XX or 45 A + XY, i.e. 47 chromosomes","Short stature, small round head, broad flat face, simian crease, congenital heart disease"],["Klinefelter''s syndrome","Additional X chromosome in male; 44 A + XXY, i.e. 47 chromosomes","Gynaecomastia, sterile, mentally retarded"],["Turner''s syndrome","Absence of one X chromosome in female; 44 A + X0, i.e. 45 chromosomes","Sterile, rudimentary ovaries, lack of secondary sexual characters, dwarf, mentally retarded"]]}'::jsonb, null, null, '{"recall_question":"Which syndrome has genetic constitution 44 A + XXY?","reveal_answer":"Klinefelter''s syndrome.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 112, 30, true),
  ('neet-biology-molecular-basis-of-inheritance-genetic-material-overview', 'neet-biology-molecular-basis-of-inheritance', 'DNA and RNA as Genetic Material', 'concept', 'Nucleic acids are the building blocks of genetic material.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["DNA","Genetic material in most organisms"],["RNA","Genetic material in some viruses; mostly functions as messengers"],["RNA world","RNA was the first genetic material; acts as genetic material and catalyst"],["DNA from RNA","DNA evolved from RNA for stability"]]}'::jsonb, null, null, '{"recall_question":"What is the genetic material in most organisms?","reveal_answer":"DNA.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 147, 1, true),
  ('neet-biology-molecular-basis-of-inheritance-nucleotide-vs-nucleoside', 'neet-biology-molecular-basis-of-inheritance', 'Nucleotide vs Nucleoside', 'comparison', 'Polynucleotides are polymers of nucleotides.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Term","Source-backed components/bond"],"rows":[["Nucleoside","Nitrogenous base linked to OH of 1'' C pentose sugar through N-glycosidic linkage"],["Nucleotide","Phosphate group linked to OH of 5'' C of a nucleoside through phosphoester linkage"],["Dinucleotide","Two nucleotides linked by 3''-5'' phosphodiester bond"],["Polynucleotide","More nucleotides linked together"]]}'::jsonb, null, null, '{"recall_question":"Which bond links two nucleotides in a dinucleotide?","reveal_answer":"3''-5'' phosphodiester bond.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 147, 2, true),
  ('neet-biology-molecular-basis-of-inheritance-purines-vs-pyrimidines', 'neet-biology-molecular-basis-of-inheritance', 'Purines vs Pyrimidines', 'comparison', 'Nitrogen bases are purines or pyrimidines.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Base group","Bases","Source-backed note"],"rows":[["Purines","Adenine and Guanine","A and G"],["Pyrimidines","Cytosine, Thymine and Uracil","Thymine only in DNA; Uracil only in RNA"]]}'::jsonb, null, null, '{"recall_question":"Which nitrogen bases are purines?","reveal_answer":"Adenine and Guanine.","key_points":[],"examples":[],"neet_traps":["Thymine is present only in DNA; Uracil only in RNA."]}'::jsonb, 5, 147, 3, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-double-helix', 'neet-biology-molecular-basis-of-inheritance', 'DNA Double Helix', 'diagram', 'Watson and Crick proposed the double helix model of DNA in 1953.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Source-backed detail"],"rows":[["Chains","Two polynucleotide chains coiled in right-handed fashion"],["Backbone","Sugar and phosphates"],["Polarity","Antiparallel: one strand 5''->3'' and other 3''->5''"],["Base pairing","A=T with 2 hydrogen bonds; C=G with 3 hydrogen bonds"],["Uniform distance","Purine comes opposite pyrimidine"]]}'::jsonb, '{"type":"bio-dna-double-helix"}'::jsonb, null, '{"recall_question":"What base pairs with adenine in DNA?","reveal_answer":"Thymine, with 2 hydrogen bonds.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 147, 4, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-dimensions', 'neet-biology-molecular-basis-of-inheritance', 'DNA Dimensions and Counts', 'fact', 'The source gives exact DNA structural values and genome sizes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed value"],"rows":[["Pitch of helix","3.4 nm (34 A)"],["Base pairs in each turn","10"],["Distance between adjacent base pairs","0.34 nm (3.4 A)"],["phi 174 bacteriophage","5386 nucleotides"],["Bacteriophage lambda","48502 base pairs"],["E. coli","4.6 x 10^6 bp"],["Haploid human DNA","3.3 x 10^9 bp"],["Length of human DNA","2.2 m"]]}'::jsonb, null, null, '{"recall_question":"What is the distance between adjacent DNA base pairs?","reveal_answer":"0.34 nm (3.4 A).","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 147, 5, true),
  ('neet-biology-molecular-basis-of-inheritance-chargaff-rule', 'neet-biology-molecular-basis-of-inheritance', 'Chargaff''s Rule', 'fact', 'Erwin Chargaff''s rule relates base proportions in DNA.', '[{"label":"Chargaff relation","latex":"[A]+[G]=[T]+[C]\\;\\text{ or }\\;\\frac{[A]+[G]}{[T]+[C]}=1"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Base relation","Source-backed detail"],"rows":[["A and T","Proportion of A is equal to T"],["G and C","Proportion of G is equal to C"]]}'::jsonb, null, null, '{"recall_question":"If A is 30.7% in DNA, what is T according to Chargaff''s rule?","reveal_answer":"30.7%.","key_points":["The source states A equals T and G equals C."],"examples":[],"neet_traps":[]}'::jsonb, 5, 147, 6, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-packaging', 'neet-biology-molecular-basis-of-inheritance', 'DNA Packaging', 'diagram', 'Eukaryotic DNA wraps around histone octamers to form nucleosomes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Prokaryotes","Negatively charged DNA is held with positively charged proteins to form nucleoid"],["Histones","Positively charged basic proteins rich in lysines and arginines"],["Histone octamer","8 histones form histone octamer"],["Nucleosome","DNA wrapped around histone octamer"],["Typical nucleosome","Contains 200 bp"],["Human nucleosomes","3.3 x 10^7"]]}'::jsonb, '{"type":"bio-nucleosome-packaging"}'::jsonb, null, '{"recall_question":"How many histones form a histone octamer?","reveal_answer":"8 histones.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 147, 7, true),
  ('neet-biology-molecular-basis-of-inheritance-euchromatin-vs-heterochromatin', 'neet-biology-molecular-basis-of-inheritance', 'Euchromatin vs Heterochromatin', 'comparison', 'Chromatin has two forms in the source.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Euchromatin","Heterochromatin"],"rows":[["Packing","Loosely packed","Densely packed"],["Activity","Transcriptionally active","Inactive"],["Staining","Stains light","Stains dark"]]}'::jsonb, null, null, '{"recall_question":"Which chromatin is transcriptionally active?","reveal_answer":"Euchromatin.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 148, 8, true),
  ('neet-biology-molecular-basis-of-inheritance-griffith-experiment', 'neet-biology-molecular-basis-of-inheritance', 'Griffith Transforming Principle', 'process', 'Griffith used mice and Streptococcus pneumoniae to show transformation.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Injection","Result"],"rows":[["S-strain","Mice die"],["R-strain","Mice live"],["Heat-killed S-strain","Mice live"],["Heat-killed S-strain + live R-strain","Mice die"]]}'::jsonb, '{"type":"bio-griffith-experiment"}'::jsonb, null, '{"recall_question":"What did Griffith call the transferred factor?","reveal_answer":"Transforming principle.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 148, 9, true),
  ('neet-biology-molecular-basis-of-inheritance-avery-macleod-mccarty', 'neet-biology-molecular-basis-of-inheritance', 'Avery, MacLeod and McCarty', 'process', 'They determined the biochemical nature of Griffith''s transforming principle.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Treatment","Source-backed conclusion"],"rows":[["Proteases and RNases","Digestion of protein and RNA did not affect transformation"],["DNase","Digestion of DNA inhibited transformation"],["Conclusion","DNA caused transformation of R cells to S cells; DNA was the transforming principle"]]}'::jsonb, null, null, '{"recall_question":"Which enzyme treatment inhibited transformation?","reveal_answer":"DNase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 148, 10, true),
  ('neet-biology-molecular-basis-of-inheritance-hershey-chase', 'neet-biology-molecular-basis-of-inheritance', 'Hershey-Chase Experiment', 'process', 'The blender experiment proved DNA is the genetic material.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Label","Source-backed result"],"rows":[["P32","Radioactive DNA, because only DNA contains phosphorus"],["S35","Radioactive protein, because protein contains sulphur"],["Radioactive DNA viruses","Bacteria became radioactive; DNA entered bacteria"],["Radioactive protein viruses","Bacteria were not radioactive; proteins did not enter bacteria"]]}'::jsonb, null, null, '{"recall_question":"Which isotope labelled DNA in Hershey-Chase?","reveal_answer":"P32.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 148, 11, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-vs-rna-genetic-material', 'neet-biology-molecular-basis-of-inheritance', 'DNA vs RNA as Genetic Material', 'comparison', 'DNA is better for storage; RNA is better for transmission of genetic information.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","DNA","RNA"],"rows":[["Stability/reactivity","Less reactive and stable","Highly reactive and unstable"],["Strands","Double stranded","Single stranded"],["Base","Presence of thymine","Presence of uracil"],["Sugar","Absence of 2''-OH","Presence of 2''-OH"],["Role","Better for storage of genetic information","Better for transmission; directly codes protein synthesis"]]}'::jsonb, null, null, '{"recall_question":"Why is DNA better for storage in the source?","reveal_answer":"It is more stable due to double stranded nature, thymine and absence of 2''-OH.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 148, 12, true),
  ('neet-biology-molecular-basis-of-inheritance-central-dogma', 'neet-biology-molecular-basis-of-inheritance', 'Central Dogma', 'diagram', 'Francis Crick proposed central dogma of molecular biology.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Flow","Source-backed recall"],"rows":[["Central dogma","Genetic information flows from DNA -> RNA -> Protein"],["Reverse transcription","In some viruses, information flows from RNA to DNA"]]}'::jsonb, '{"type":"bio-central-dogma"}'::jsonb, null, '{"recall_question":"Who proposed central dogma?","reveal_answer":"Francis Crick.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 149, 13, true),
  ('neet-biology-molecular-basis-of-inheritance-semiconservative-replication', 'neet-biology-molecular-basis-of-inheritance', 'Semiconservative Replication', 'concept', 'Watson and Crick proposed semiconservative replication.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Replication","Copying of DNA from parental DNA"],["Model","Parental DNA strands act as templates for new complementary strands"],["After replication","Each DNA molecule has one parental and one new strand"],["Proved by","Matthew Messelson and Franklin Stahl in 1958"]]}'::jsonb, null, null, '{"recall_question":"What does semiconservative replication mean?","reveal_answer":"Each new DNA molecule has one parental strand and one new strand.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 149, 14, true),
  ('neet-biology-molecular-basis-of-inheritance-meselson-stahl', 'neet-biology-molecular-basis-of-inheritance', 'Messelson-Stahl Experiment', 'process', 'E. coli DNA shifted from heavy to light nitrogen showed semiconservative replication.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Stage","Source-backed result"],"rows":[["15NH4Cl medium","15N incorporated into newly synthesized heavy DNA"],["After one generation or 20 minutes in 14NH4Cl","DNA density intermediate or hybrid"],["After second generation or 40 minutes","Equal amounts of hybrid DNA and light DNA"],["Taylor and colleagues, 1958","Vicia faba radioactive thymidine experiments proved chromosome DNA also replicates semiconservatively"]]}'::jsonb, null, null, '{"recall_question":"What appeared after one generation in Messelson-Stahl?","reveal_answer":"Intermediate or hybrid DNA.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 149, 15, true),
  ('neet-biology-molecular-basis-of-inheritance-replication-machinery', 'neet-biology-molecular-basis-of-inheritance', 'Replication Machinery', 'sequence', 'Replication starts at origin and proceeds at replication forks.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step/component","Source-backed role"],"rows":[["Origin or ori","Point where DNA replication starts"],["Replicon","Unit of replication with one origin"],["Helicase","Breaks H-bonds so strands unwind and separate"],["Replication fork","Y-shaped structure formed by unwinding"],["Primase","Synthesizes a small RNA primer"],["DNA polymerase","Adds nucleotides and can proof-read"],["DNA ligase","Joins Okazaki fragments"]]}'::jsonb, '{"type":"bio-replication-fork"}'::jsonb, null, '{"recall_question":"Which enzyme joins Okazaki fragments?","reveal_answer":"DNA ligase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 149, 16, true),
  ('neet-biology-molecular-basis-of-inheritance-leading-vs-lagging', 'neet-biology-molecular-basis-of-inheritance', 'Leading vs Lagging Strand', 'comparison', 'Both strands are synthesized in 5''->3'' direction, but one is continuous and one discontinuous.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Leading strand","Lagging strand"],"rows":[["Synthesis","Continuous stretch","Small stretches or Okazaki fragments"],["Direction","5''->3''","5''->3''"],["Joining","No Okazaki fragment joining described","Okazaki fragments joined by DNA ligase"]]}'::jsonb, null, null, '{"recall_question":"Which strand has Okazaki fragments?","reveal_answer":"Lagging strand.","key_points":[],"examples":[],"neet_traps":["Both new strands are formed in 5''->3'' direction in the source."]}'::jsonb, 5, 149, 17, true),
  ('neet-biology-molecular-basis-of-inheritance-replication-values', 'neet-biology-molecular-basis-of-inheritance', 'Replication Values', 'fact', 'The source gives specific replication timing values.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed value"],"rows":[["E. coli replication completion","18 minutes"],["E. coli rate","2000 bp per second"],["Eukaryotic DNA replication","S-phase of cell cycle"],["Failure of cell division after DNA replication","Polyploidy"]]}'::jsonb, null, null, '{"recall_question":"When does DNA replication occur in eukaryotes?","reveal_answer":"S-phase of cell cycle.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 149, 18, true),
  ('neet-biology-molecular-basis-of-inheritance-transcription-overview', 'neet-biology-molecular-basis-of-inheritance', 'Transcription Overview', 'concept', 'Transcription copies genetic information from one DNA strand into RNA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Base pairing","Adenine pairs with uracil instead of thymine"],["Enzyme","DNA-dependent RNA polymerase"],["Polymerization","Only in 5''->3'' direction"],["Template strand","3''->5'' strand; RNA is built from this"],["Coding strand","5''->3'' strand; copied to RNA"]]}'::jsonb, null, null, '{"recall_question":"Which strand acts as template during transcription?","reveal_answer":"3''->5'' template strand.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 149, 19, true),
  ('neet-biology-molecular-basis-of-inheritance-transcription-unit', 'neet-biology-molecular-basis-of-inheritance', 'Transcription Unit', 'diagram', 'A transcription unit lies between initiation and termination sites.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Region","Source-backed recall"],"rows":[["Promoter","Binding site for RNA polymerase; located towards 5''-end upstream"],["Structural gene","Region between promoter and terminator where transcription takes place"],["Terminator","Site where transcription stops; located towards 3''-end downstream"]]}'::jsonb, '{"type":"bio-transcription-unit"}'::jsonb, null, '{"recall_question":"Where does RNA polymerase bind in a transcription unit?","reveal_answer":"Promoter.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 150, 20, true),
  ('neet-biology-molecular-basis-of-inheritance-monocistronic-vs-polycistronic', 'neet-biology-molecular-basis-of-inheritance', 'Monocistronic vs Polycistronic', 'comparison', 'Structural genes differ in eukaryotes and prokaryotes.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Monocistronic structural genes","Polycistronic structural genes"],"rows":[["Seen in","Eukaryotes","Prokaryotes"],["Split genes","Coding exons interrupted by introns","No split genes"],["mRNA","Exons appear in processed mRNA; introns do not","Multiple coding regions function together"]]}'::jsonb, null, null, '{"recall_question":"Which sequences appear in processed mRNA?","reveal_answer":"Exons.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 150, 21, true),
  ('neet-biology-molecular-basis-of-inheritance-transcription-steps', 'neet-biology-molecular-basis-of-inheritance', 'Transcription Steps', 'sequence', 'In bacteria, one RNA polymerase catalyses synthesis of all types of RNA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["Initiation","RNA polymerase binds promoter; sigma factor initiates RNA synthesis"],["Elongation","RNA chain synthesized in 5''->3'' direction with ATP, GTP, UTP and CTP"],["Termination","rho factor binds RNA polymerase and terminates transcription"]]}'::jsonb, null, null, '{"recall_question":"Which factor terminates bacterial transcription?","reveal_answer":"rho factor.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 150, 22, true),
  ('neet-biology-molecular-basis-of-inheritance-rna-polymerases-processing', 'neet-biology-molecular-basis-of-inheritance', 'Eukaryotic RNA Polymerases and Processing', 'classification', 'Eukaryotic primary transcripts contain exons and introns and require processing.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Process/enzyme","Source-backed detail"],"rows":[["RNA polymerase I","Transcribes rRNAs: 28S, 18S and 5.8S"],["RNA polymerase II","Transcribes hnRNA, precursor of mRNA"],["RNA polymerase III","Transcribes tRNA, 5S rRNA and snRNAs"],["Splicing","Introns removed and exons joined"],["Capping","Methyl guanosine triphosphate cap added to 5'' end of hnRNA"],["Tailing","200-300 adenylate residues added at 3'' end"]]}'::jsonb, null, null, '{"recall_question":"Which RNA polymerase transcribes hnRNA?","reveal_answer":"RNA polymerase II.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 150, 23, true),
  ('neet-biology-molecular-basis-of-inheritance-genetic-code-features', 'neet-biology-molecular-basis-of-inheritance', 'Genetic Code Features', 'classification', 'A codon is a sequence of three bases determining a single amino acid.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Source-backed detail"],"rows":[["Triplet","Three-letter code; 64 codons"],["Coding codons","61 codons code for amino acids"],["Stop codons","UAA, UAG and UGA"],["Universal","UUU codes for Phenylalanine from bacteria to human, with exceptions in mitochondrial codons and some protozoans"],["Comma less","No punctuation between adjacent codons"],["Non-overlapping","Codons do not overlap"],["Degenerate","More than one codon can code one amino acid except AUG and UGG"],["Unambiguous and specific","One codon specifies only one amino acid"],["AUG","Codes Methionine and acts as initiator codon"]]}'::jsonb, null, null, '{"recall_question":"Name the three stop codons.","reveal_answer":"UAA, UAG and UGA.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 151, 24, true),
  ('neet-biology-molecular-basis-of-inheritance-genetic-code-scientists', 'neet-biology-molecular-basis-of-inheritance', 'Genetic Code Scientists', 'fact', 'The source links several scientists to deciphering the genetic code.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Scientist","Source-backed contribution"],"rows":[["George Gamow","Suggested code should be made of 3 nucleotides for 20 amino acids"],["Har Gobind Khorana","Developed chemical method for synthesizing RNA molecules with defined base combinations"],["Marshall Nirenberg","Developed cell-free system for protein synthesis"],["Severo Ochoa","Polynucleotide phosphorylase used to polymerize RNA with defined sequences in template-independent manner"]]}'::jsonb, null, null, '{"recall_question":"Who suggested the triplet nature of genetic code?","reveal_answer":"George Gamow.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 150, 25, true),
  ('neet-biology-molecular-basis-of-inheritance-types-of-rna', 'neet-biology-molecular-basis-of-inheritance', 'Types of RNA', 'classification', 'The source lists mRNA, rRNA and tRNA roles.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["RNA","Source-backed role"],"rows":[["mRNA","Provides template for translation"],["rRNA","Structural and catalytic role during translation; 23S rRNA in bacteria acts as ribozyme"],["tRNA","Brings amino acids for protein synthesis and reads genetic code"]]}'::jsonb, null, null, '{"recall_question":"Which RNA acts as adapter molecule?","reveal_answer":"tRNA.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 151, 26, true),
  ('neet-biology-molecular-basis-of-inheritance-trna', 'neet-biology-molecular-basis-of-inheritance', 'tRNA Structure', 'fact', 'tRNA is called adapter molecule because it links codon reading with amino-acid binding.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed recall"],"rows":[["Anticodon loop","Has bases complementary to codon"],["Amino acid acceptor end","Amino acid binds here"],["Ribosome binding loop","Listed tRNA part"],["Enzyme binding loop","Listed tRNA part"],["2-D structure","Clover-leaf"],["3-D structure","Inverted L"],["Stop codons","No tRNAs for stop codons"]]}'::jsonb, null, null, '{"recall_question":"What is the 2-D structure of tRNA like?","reveal_answer":"Clover-leaf.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 151, 27, true),
  ('neet-biology-molecular-basis-of-inheritance-translation-steps', 'neet-biology-molecular-basis-of-inheritance', 'Translation Steps', 'sequence', 'Translation polymerizes amino acids into a polypeptide according to mRNA codons.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["Charging or aminoacylation","Amino acid activated with ATP and linked to cognate tRNA by aminoacyl tRNA synthetase"],["Initiation","Small ribosomal subunit binds mRNA at start codon AUG; initiator tRNA binds P site"],["Elongation","Second aminoacyl tRNA binds A site and peptide bond forms by peptidyl transferase"],["Termination","Release factor binds stop codon and translation terminates"]]}'::jsonb, '{"type":"bio-translation-flow"}'::jsonb, null, '{"recall_question":"Which enzyme charges tRNA?","reveal_answer":"Aminoacyl tRNA synthetase.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 151, 28, true),
  ('neet-biology-molecular-basis-of-inheritance-transcription-vs-translation', 'neet-biology-molecular-basis-of-inheritance', 'Transcription vs Translation', 'comparison', 'Transcription makes RNA from DNA; translation makes polypeptide from mRNA.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Transcription","Translation"],"rows":[["Definition","Copying genetic information from one DNA strand into RNA","Polymerisation of amino acids to form polypeptide based on mRNA codons"],["Main enzyme/machine","DNA-dependent RNA polymerase","Ribosome"],["Direction/process","RNA polymerized in 5''->3'' direction","Ribosome moves codon to codon"],["Product","RNA","Polypeptide"]]}'::jsonb, null, null, '{"recall_question":"Which process produces a polypeptide?","reveal_answer":"Translation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 151, 29, true),
  ('neet-biology-molecular-basis-of-inheritance-lac-operon', 'neet-biology-molecular-basis-of-inheritance', 'Lac Operon', 'diagram', 'Lac operon controls lactose metabolism in E. coli and was proposed by Francois Jacob and Jacque Monod.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Part","Source-backed role"],"rows":[["Regulatory or inhibitor i gene","Codes repressor protein"],["z gene","Codes beta-galactosidase; hydrolyses lactose to galactose and glucose"],["y gene","Codes permease; increases permeability to beta-galactosides"],["a gene","Codes transacetylase"],["No lactose","Repressor binds operator and blocks RNA polymerase movement"],["Lactose/allolactose present","Inducer binds repressor, operator becomes free and transcription starts"]]}'::jsonb, '{"type":"bio-lac-operon"}'::jsonb, null, '{"recall_question":"What is the inducer in lac operon?","reveal_answer":"Lactose or allolactose.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 152, 30, true),
  ('neet-biology-molecular-basis-of-inheritance-gene-expression-levels', 'neet-biology-molecular-basis-of-inheritance', 'Gene Expression Levels', 'classification', 'In eukaryotes, gene expression can be regulated at multiple levels.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Level","Source-backed recall"],"rows":[["Transcriptional level","Formation of primary transcript"],["Processing level","Splicing, capping etc."],["Transport level","Transport of mRNA from nucleus to cytoplasm"],["Translational level","Formation of polypeptide"],["Induction","A set of genes is switched on when substrate is added"],["Repression","Genes to produce a metabolite are turned off when product is added"]]}'::jsonb, null, null, '{"recall_question":"What is induction in gene expression?","reveal_answer":"Switching on a set of genes to metabolize an added substrate.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 152, 31, true),
  ('neet-biology-molecular-basis-of-inheritance-hgp-overview-goals', 'neet-biology-molecular-basis-of-inheritance', 'Human Genome Project', 'fact', 'HGP was the first mega project for sequencing nucleotides and mapping genes in the human genome.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Genome","Entire DNA in haploid set of chromosomes"],["Human genome packaging","DNA packed in 23 chromosomes"],["Human genome size","About 3 x 10^9 bp"],["Project duration","1990-2003"],["Coordinated by","U.S. Department of Energy and National Institute of Health"],["Goal","Identify estimated genes and sequence 3 billion chemical base pairs of human DNA"]]}'::jsonb, null, null, '{"recall_question":"What was the duration of HGP in the source?","reveal_answer":"1990-2003.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 152, 32, true),
  ('neet-biology-molecular-basis-of-inheritance-hgp-methodology', 'neet-biology-molecular-basis-of-inheritance', 'HGP Methodology', 'sequence', 'The source outlines sequencing from DNA isolation to computer alignment.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step/approach","Source-backed recall"],"rows":[["ESTs","Focused on identifying all genes expressed as RNA"],["Sequence annotation","Sequencing coding and non-coding genome then assigning functions"],["Procedure","Isolate DNA -> random fragments -> clone in host using BAC/YAC -> sequence by automated DNA sequencers -> arrange overlapping regions -> align using computer programs"],["Bioinformatics","Application of computer science and information technology to biology and medicine"],["Last sequenced chromosome","Chromosome 1, May 2006"]]}'::jsonb, null, null, '{"recall_question":"Which chromosome was last sequenced in HGP?","reveal_answer":"Chromosome 1 in May 2006.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 153, 33, true),
  ('neet-biology-molecular-basis-of-inheritance-hgp-salient-features', 'neet-biology-molecular-basis-of-inheritance', 'HGP Salient Features', 'fact', 'The source gives exact findings from the Human Genome Project.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Source-backed value/detail"],"rows":[["Human genome bases","3164.7 million nucleotide bases"],["Genes","About 30,000"],["Average gene","3000 bases"],["Largest known human gene","Dystrophin on X-chromosome, 2.4 million bases"],["Similarity","99.9% nucleotide bases are same in all people"],["Difference","0.1% or 3 x 10^6 bp makes every individual unique"],["Protein-coding genome","Less than 2%"],["SNPs","About 1.4 million locations"],["Chromosomes","Chromosome I has most genes, 2968; Y has fewest, 231"]]}'::jsonb, null, null, '{"recall_question":"What percentage of human genome codes for proteins in the source?","reveal_answer":"Less than 2%.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 153, 34, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-fingerprinting-basis', 'neet-biology-molecular-basis-of-inheritance', 'DNA Fingerprinting Basis', 'concept', 'DNA fingerprinting identifies similarities and differences in DNA fragments of two individuals.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Developed by","Alec Jeffreys, 1985"],["Satellite DNA","Small peaks of repetitive DNA separated from bulk genomic DNA"],["VNTR","Variable number tandem repeats; tandemly repeated DNA sequence in many copy numbers"],["Size of VNTR","0.1 to 20 kb"],["Specificity","VNTR is specific from person to person"],["Exception","DNA fingerprint differs in everyone except monozygotic identical twins"]]}'::jsonb, null, null, '{"recall_question":"What does VNTR stand for?","reveal_answer":"Variable number tandem repeats.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 153, 35, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-fingerprinting-steps', 'neet-biology-molecular-basis-of-inheritance', 'DNA Fingerprinting Steps', 'sequence', 'The source presents DNA fingerprinting as Southern blotting technique.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Step","Source-backed event"],"rows":[["1","Isolation of DNA from cells, blood stains, semen stains, saliva, hair roots, bone, skin etc."],["2","Digestion of DNA by restriction endonucleases"],["3","Separation of DNA fragments by gel electrophoresis"],["4","Transfer DNA fragments to nitrocellulose or nylon membranes"],["5","Hybridization using radioactive labelled VNTR probe"],["6","Detection by autoradiography"]]}'::jsonb, null, null, '{"recall_question":"Which probe is used in DNA fingerprinting?","reveal_answer":"Radioactive labelled VNTR probe.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 153, 36, true),
  ('neet-biology-molecular-basis-of-inheritance-dna-fingerprinting-applications', 'neet-biology-molecular-basis-of-inheritance', 'DNA Fingerprinting Applications', 'examples', 'PCR can increase sensitivity so DNA from a single cell is enough.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Application","Source-backed use"],"rows":[["Forensic tool","Solve paternity, rape, murder etc."],["Medical","Diagnosis of genetic diseases"],["Evolutionary","Determine phylogenetic status of animals"],["Population","Determine population and genetic diversities"]]}'::jsonb, null, null, '{"recall_question":"Which technique increases DNA fingerprinting sensitivity?","reveal_answer":"Polymerase chain reaction, PCR.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 154, 37, true),
  ('neet-biology-evolution-evolution-overview', 'neet-biology-evolution', 'Evolution Overview', 'concept', 'Evolution is an orderly change from one form to another.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed recall"],"rows":[["Evolutionary Biology","Study of evolutionary history of life forms"],["Big Bang","Universe originated about 20 billion years ago by a singular huge explosion"],["Earth formed","About 4.5 billion years ago"],["Life appeared","Almost four billion years ago"]]}'::jsonb, null, null, '{"recall_question":"What is evolutionary biology?","reveal_answer":"Study of evolutionary history of life forms.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 113, 1, true),
  ('neet-biology-evolution-origin-of-life-theories', 'neet-biology-evolution', 'Origin of Life Theories', 'comparison', 'The source contrasts older origin theories with chemical evolution.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Theory","Source-backed recall"],"rows":[["Spontaneous generation or abiogenesis","Life came out of decaying and rotting matter; disproved by Louis Pasteur"],["Biogenesis","Life originates from pre-existing life; proposed by Francisco Redi, Spallanzani and Louis Pasteur"],["Panspermia","Units of life or spores transferred to different planets including earth"],["Special creation","Living things created by supernatural power"],["Chemical evolution","First life originated from non-living inorganic and organic molecules; proposed by Oparin and Haldane"]]}'::jsonb, null, null, '{"recall_question":"Who proposed chemical evolution in the source?","reveal_answer":"Oparin and Haldane.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 113, 2, true),
  ('neet-biology-evolution-urey-miller', 'neet-biology-evolution', 'Urey-Miller Experiment', 'process', 'Urey and Miller experimentally supported chemical evolution.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Scientists","Harold Urey and Stanley Miller"],["Condition","Primitive-earth-like high temperature, volcanic storms and reducing atmosphere"],["Gases","CH4, NH3, H2O and H2"],["Temperature","800°C"],["Result","Some amino acids were formed"],["Similar experiments","Formation of sugars, nitrogen bases, pigment and fats"]]}'::jsonb, '{"type":"bio-urey-miller"}'::jsonb, null, '{"recall_question":"What was formed in Urey-Miller experiment?","reveal_answer":"Some amino acids.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 113, 3, true),
  ('neet-biology-evolution-first-life-forms', 'neet-biology-evolution', 'First Life Forms', 'fact', 'The source gives a compact origin timeline.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Time","Source-backed event"],"rows":[["3 billion years ago","First non-cellular forms of life originated"],["Non-cellular forms","Self-replicating metabolic capsule containing RNA, proteins, polysaccharides etc."],["2000 mya","First cellular forms of life appeared"],["Photosynthetic cells","Some cells could release O2 as light reaction in photosynthesis"]]}'::jsonb, null, null, '{"recall_question":"When did first non-cellular forms of life originate in the source?","reveal_answer":"3 billion years ago.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 113, 4, true),
  ('neet-biology-evolution-fossil-evidence', 'neet-biology-evolution', 'Fossil Evidence', 'classification', 'Fossils are remnants of life forms found in rocks and are written documents of evolution.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Use of fossils","Source-backed example/detail"],"rows":[["Phylogeny","Study evolutionary history; example horse evolution"],["Connecting link","Example Archaeopteryx"],["Extinct animals","Example dinosaurs"],["Geological periods","Analyse fossils in different sedimentary rock layers"]]}'::jsonb, null, null, '{"recall_question":"Which source example is a connecting link?","reveal_answer":"Archaeopteryx.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 113, 5, true),
  ('neet-biology-evolution-homologous-vs-analogous', 'neet-biology-evolution', 'Homologous vs Analogous Organs', 'comparison', 'Homology indicates common ancestry; analogy indicates convergent evolution.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Feature","Homologous organs","Analogous organs"],"rows":[["Structure/origin","Fundamentally similar structure and origin","Different structure and origin"],["Function","Different functions","Similar function"],["Evolution","Divergent evolution","Convergent evolution"],["Examples","Human hand, whale flipper, bat wing, cheetah foot; Bougainvillea thorn and Cucurbita tendril","Insect wing and bird wing; octopus and mammal eyes; penguin and dolphin flipper; sweet potato and potato"]]}'::jsonb, '{"type":"bio-homology-analogy"}'::jsonb, null, '{"recall_question":"Which organs indicate divergent evolution?","reveal_answer":"Homologous organs.","key_points":[],"examples":[],"neet_traps":["Analogous organs indicate convergent evolution."]}'::jsonb, 5, 113, 6, true),
  ('neet-biology-evolution-adaptive-radiation', 'neet-biology-evolution', 'Adaptive Radiation', 'concept', 'Adaptive radiation is evolution of different species from an ancestor in a geographical area starting from a point.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Cue","Source-backed detail"],"rows":[["Type","A type of divergent evolution"],["Examples","Darwin''s finches in Galapagos Islands, Australian marsupials, placental mammals in Australia"],["Multiple radiations in isolated area","Results in convergent evolution"],["Example","Australian marsupials and placental mammals"]]}'::jsonb, null, null, '{"recall_question":"Darwin''s finches are an example of what?","reveal_answer":"Adaptive radiation.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 114, 7, true),
  ('neet-biology-evolution-marsupial-placental-comparison', 'neet-biology-evolution', 'Marsupial and Placental Mammal Pairings', 'examples', 'The source pairs Australian marsupials with placental mammals.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Placental mammal","Australian marsupial"],"rows":[["Mole","Marsupial mole"],["Ant eater","Numbat or ant eater"],["Mouse","Marsupial mouse"],["Lemur","Spotted cuscus"],["Flying squirrel","Flying phalanger"],["Bobcat","Tasmanian tiger cat"],["Wolf","Tasmanian wolf"]]}'::jsonb, null, null, '{"recall_question":"Which marsupial corresponds to placental wolf?","reveal_answer":"Tasmanian wolf.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 114, 8, true),
  ('neet-biology-evolution-biochemical-embryological-evidence', 'neet-biology-evolution', 'Biochemical and Embryological Evidence', 'comparison', 'The source includes biochemical similarities and embryological observations.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Evidence","Source-backed recall"],"rows":[["Biochemical","Similarities in proteins, genes, biomolecules and metabolism indicate common ancestry"],["Embryological","Ernst Haeckel observed common features in vertebrate embryos absent in adults"],["Gill slits","All vertebrate embryos, including human, develop vestigial gill slits behind head; functional only in fish"],["Rejection","Karl Ernst von Baer rejected Haeckel''s proposal; embryos never pass through adult stages of other animals"]]}'::jsonb, null, null, '{"recall_question":"Who rejected Haeckel''s embryological proposal?","reveal_answer":"Karl Ernst von Baer.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 4, 114, 9, true),
  ('neet-biology-evolution-industrial-melanism', 'neet-biology-evolution', 'Industrial Melanism', 'process', 'Industrial melanism is source evidence for natural selection.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"columns":["Period","Source-backed observation/reason"],"rows":[["Before industrialization, 1850s","More white-winged moths, Biston betularia, than dark melanised moths"],["Reason before","White lichens covered trees; white moths survived, dark moths picked by predators"],["After industrialization, 1920","More dark-winged moths and fewer white-winged moths developed"],["Reason after","Tree trunks darkened by smoke and soot; no lichens; dark moths survived"]]}'::jsonb, null, null, '{"recall_question":"Which moth form increased after industrialization?","reveal_answer":"Dark-winged or melanised moths.","key_points":[],"examples":[],"neet_traps":[]}'::jsonb, 5, 114, 10, true),
